def regions(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; R=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==col and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                R.append((min(rs),max(rs),min(cs),max(cs),col,cells))
    return R

def transform(g):
    R=regions(g)
    out=[row[:] for row in g]
    for k,(r0,r1,c0,c1,col,cells) in enumerate(R):
        depth=sum(1 for m,(a0,a1,b0,b1,oc,_) in enumerate(R) if m!=k and oc!=col and a0<=r0 and r1<=a1 and b0<=c0 and c1<=b1)
        R[k]=R[k]+(depth,)
    # group: object = outermost region; assign each region to the outermost region containing it
    depthmap={}
    for r0,r1,c0,c1,col,cells,depth in R:
        depthmap.setdefault(depth,[]).append(col)
    # regions at same depth may belong to different objects; handle per-object via containment chain
    # simpler: mapping per region = reverse order within its containment chain
    def chain(region):
        r0,r1,c0,c1,col,cells,depth=region
        ch=[region]
        cur=region
        while True:
            r0,r1,c0,c1,col,_,_=cur
            nxt=None
            for m in R:
                a0,a1,b0,b1,oc,_,d=m
                if d==depth+1 and oc!=col and a0<=r0 and r1<=a1 and b0<=c0 and c1<=b1:
                    # ensure directly nested (no intermediate)
                    inter=[q for q in R if q is not m and q[6]>depth and q[0]>=a0 and q[1]<=a1 and q[2]>=b0 and q[3]<=b1 and q[0]<=r0 and r1<=q[1] and q[2]<=c0 and c1<=q[3]]
                    if not inter:
                        nxt=m; break
            if nxt is None: break
            ch.append(nxt); cur=nxt
        return ch
    mapped=set()
    for reg in R:
        if reg[0] in mapped: continue
        ch=chain(reg)
        cols=[c for _,_,_,_,c,_,_ in ch]
        mp={a:b for a,b in zip(cols,cols[::-1])}
        for _,_,_,_,_,cells,_ in ch:
            for r,c in cells:
                out[r][c]=mp[g[r][c]]
                mapped.add((r0,r1,c0,c1,col))
    return out

